# Free RAM next to the Z5 profile byte.
# A byte is free when the stock image holds 0xFF there and the Z5 CSV does not write it.
# Do not edit this file after it has run.
import csv
import json
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
CSV = ROOT / 'ref/analysis/button-af/readiness/t5-afon-button-handoff/out/overlay-changed-bytes.csv'
OUT = ROOT / 'work/out/ram-gaps-m1.json'
BASE = 0x60021020
LO = 0x6031E800
HI = 0x60322000

image = IMAGE.read_bytes()
occupied = {}
with CSV.open(encoding='utf-8', newline='') as f:
    for row in csv.DictReader(f):
        addr = int(row['runtime_address'], 16)
        occupied[addr] = {
            'source': row['source'],
            'stock': row['stock_byte'],
            'proposed': row['proposed_byte'],
            'purpose': row['purpose'],
        }

def image_byte(addr):
    off = addr - BASE
    if off < 0 or off >= len(image):
        return None
    return image[off]

runs = []
start = None
kind = None
for addr in range(LO, HI):
    occ = addr in occupied
    b = image_byte(addr)
    here = 'occupied' if occ else ('ff' if b == 0xFF else 'stock')
    if here != kind:
        if start is not None:
            runs.append({'start': start, 'end': addr, 'bytes': addr - start, 'kind': kind})
        start = addr
        kind = here
if start is not None:
    runs.append({'start': start, 'end': HI, 'bytes': HI - start, 'kind': kind})

free = [r for r in runs if r['kind'] == 'ff' and r['bytes'] >= 8]
head = []
for addr in range(0x6031E920, 0x6031E940):
    rec = occupied.get(addr)
    head.append({
        'addr': f'{addr:08x}',
        'image': f'{image_byte(addr):02x}',
        'z5': None if rec is None else rec['source'] + ' -> ' + rec['proposed'],
    })

# Relocated block is the uncached alias of 0x6031ed00. Report the occupied span that contains it.
block = [a for a in occupied if 0x6031ED00 <= a < 0x6031F000]
doc = {
    'image': str(IMAGE).replace('\\', '/'),
    'csv': str(CSV).replace('\\', '/'),
    'csv_rows': len(occupied),
    'range': [f'{LO:08x}', f'{HI:08x}'],
    'free_ff_runs_at_least_8': [
        {'start': f"{r['start']:08x}", 'end': f"{r['end']:08x}", 'bytes': r['bytes']} for r in free
    ],
    'head_0x6031e920': head,
    'relocated_block_occupied': {
        'count': len(block),
        'lo': f'{min(block):08x}' if block else None,
        'hi_inclusive': f'{max(block):08x}' if block else None,
    },
    'runs': [
        {'start': f"{r['start']:08x}", 'end': f"{r['end']:08x}", 'bytes': r['bytes'], 'kind': r['kind']}
        for r in runs
    ],
}
OUT.parent.mkdir(parents=True, exist_ok=True)
OUT.write_text(json.dumps(doc, indent=2) + '\n', encoding='utf-8')
print('csv_rows', len(occupied))
print('free runs >= 8:')
for r in free:
    print(f"  {r['start']:08x}..{r['end']:08x}  {r['bytes']}")
print('relocated', doc['relocated_block_occupied'])
print('head:')
for row in head:
    print(row['addr'], 'image', row['image'], 'z5', row['z5'])
